from datetime import datetime

def log_event(event_type, *messages, timestamp=None, **metadata):
    if timestamp is None:
        timestamp = datetime.now().isoformat(timespec='seconds')
    msg_part = " | ".join(messages) if messages else "(no message)"
    meta_part = ", ".join(f"{k}={v}" for k, v in metadata.items())
    if meta_part:
        return f"[{timestamp}] {event_type}: {msg_part} | {meta_part}"
    return f"[{timestamp}] {event_type}: {msg_part}"
